import React from 'react';
import { motion } from 'framer-motion';
import { useSettings } from '../../context/SettingsContext';
import styles from './Card.module.css';

const Card = ({
  children,
  variant = 'default', // 'default', 'elevated', 'outlined', 'glass'
  padding = 'md', // 'none', 'sm', 'md', 'lg'
  hoverable = false,
  onClick,
  className = '',
  ...props
}) => {
  const { settings } = useSettings();
  
  const cardVariants = {
    initial: { 
      y: 20, 
      opacity: 0 
    },
    animate: { 
      y: 0, 
      opacity: 1,
      transition: { type: 'spring', stiffness: 300, damping: 25 }
    },
    hover: hoverable ? {
      y: -4,
      boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1)',
      transition: { type: 'spring', stiffness: 400, damping: 10 }
    } : {},
  };

  const classNames = [
    styles.card,
    styles[variant],
    styles[`padding-${padding}`],
    hoverable && styles.hoverable,
    onClick && styles.clickable,
    className,
  ].filter(Boolean).join(' ');

  return (
    <motion.div
      className={classNames}
      onClick={onClick}
      variants={settings.animationsEnabled ? cardVariants : {}}
      initial="initial"
      whileInView="animate"
      viewport={{ once: true, margin: "-50px" }}
      whileHover={hoverable ? "hover" : undefined}
      {...props}
    >
      {children}
    </motion.div>
  );
};

// Card Header Component
export const CardHeader = ({ children, className = '' }) => (
  <div className={`${styles.cardHeader} ${className}`}>
    {children}
  </div>
);

// Card Title Component
export const CardTitle = ({ children, className = '' }) => (
  <h3 className={`${styles.cardTitle} ${className}`}>
    {children}
  </h3>
);

// Card Description Component
export const CardDescription = ({ children, className = '' }) => (
  <p className={`${styles.cardDescription} ${className}`}>
    {children}
  </p>
);

// Card Content Component
export const CardContent = ({ children, className = '' }) => (
  <div className={`${styles.cardContent} ${className}`}>
    {children}
  </div>
);

// Card Footer Component
export const CardFooter = ({ children, className = '' }) => (
  <div className={`${styles.cardFooter} ${className}`}>
    {children}
  </div>
);

export default Card;
